CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, username text UNIQUE NOT NULL, password bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS devices (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), name text NOT NULL, platform text NOT NULL, enabled boolean NOT NULL DEFAULT true, revoked boolean NOT NULL DEFAULT false, environment text NOT NULL DEFAULT 'sandbox', apns_token text, widget_token text, subscriptions jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS credentials (hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), device_id text REFERENCES devices(id), kind text NOT NULL, name text NOT NULL DEFAULT '', scopes jsonb NOT NULL DEFAULT '[]', targets jsonb NOT NULL DEFAULT '[]', data_ids jsonb NOT NULL DEFAULT '[]', expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pairings (hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS groups (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), name text NOT NULL, devices jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS streams (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), data_id text NOT NULL, name text NOT NULL, ordering text NOT NULL, revision bigint NOT NULL DEFAULT 0, sequence bigint, state jsonb, state_hash text, received_at timestamptz, UNIQUE(user_id,data_id));
CREATE TABLE IF NOT EXISTS messages (seq bigserial UNIQUE, id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), title text NOT NULL, body text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), notification jsonb NOT NULL, url text);
CREATE TABLE IF NOT EXISTS message_targets (message_id text NOT NULL REFERENCES messages(id), device_id text NOT NULL REFERENCES devices(id), PRIMARY KEY(message_id,device_id));
CREATE TABLE IF NOT EXISTS outbox (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), device_id text NOT NULL REFERENCES devices(id), kind text NOT NULL, resource_id text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, lease_until timestamptz, apns_id text, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(status,available_at);
CREATE TABLE IF NOT EXISTS idempotency (user_id text NOT NULL, operation text NOT NULL, key text NOT NULL, hash text NOT NULL, status integer NOT NULL, response jsonb NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(user_id,operation,key));
CREATE TABLE IF NOT EXISTS settings (key text PRIMARY KEY, value bytea NOT NULL);

CREATE TABLE IF NOT EXISTS device_keys (device_id text PRIMARY KEY REFERENCES devices(id), owner_id text NOT NULL REFERENCES users(id), registration_hash text UNIQUE, secret bytea NOT NULL);
CREATE INDEX IF NOT EXISTS device_keys_owner ON device_keys(owner_id);

CREATE TABLE IF NOT EXISTS message_routes (user_id text PRIMARY KEY REFERENCES users(id), key_hash text UNIQUE NOT NULL REFERENCES credentials(hash), secret bytea NOT NULL, devices jsonb NOT NULL, revision bigint NOT NULL DEFAULT 1);

CREATE TABLE IF NOT EXISTS card_sources (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), stream_id text UNIQUE NOT NULL REFERENCES streams(id), name text NOT NULL, mode text NOT NULL, config bytea NOT NULL, ingress bytea NOT NULL, interval_seconds integer NOT NULL DEFAULT 300, next_poll timestamptz NOT NULL DEFAULT now(), last_success timestamptz, last_error text, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS card_templates (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), source_id text NOT NULL REFERENCES card_sources(id), draft jsonb NOT NULL, draft_revision bigint NOT NULL DEFAULT 1, published jsonb, revision bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS card_import_codes (hash text PRIMARY KEY, card_id text NOT NULL REFERENCES card_templates(id), expires_at timestamptz NOT NULL, uses integer NOT NULL DEFAULT 0, max_uses integer NOT NULL DEFAULT 10, revoked boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS card_subscriptions (card_id text NOT NULL REFERENCES card_templates(id), device_id text NOT NULL REFERENCES devices(id), PRIMARY KEY(card_id,device_id));
